#!/usr/bin/python

import time
import smbus
from Adafruit_I2C import Adafruit_I2C

class ADS1015:
    """Simplified ADS1015 ADC driver for Raspberry Pi."""

    # I2C addresses
    ADDRESS_A = 0x48
    ADDRESS_B = 0x49

    # Register addresses
    REG_CONVERSION = 0x00
    REG_CONFIG = 0x01

    def __init__(self, address=ADDRESS_A, busnum=1, debug=False):
        """Initialize the ADC."""
        try:
            self.i2c = Adafruit_I2C(address, busnum=busnum, debug=debug)
        except Exception as e:
            print(f"Error initializing I2C: {e}")
            return  # Stop initialization if I2C fails

        self.address = address
        self.sps_values = {
            128: 'SPS_128': 0x8000,
            64: 'SPS_64': 0x4000,
            32: 'SPS_32': 0x0000,
            16: 'SPS_16': 0x2000,
        }
        self.pga_values = {
            6144: 'PGA_6144': 0x0000,
            4096: 'PGA_4096': 0x0200,
            2048: 'PGA_2048': 0x0400,
            1024: 'PGA_1024': 0x0600,
            512: 'PGA_512': 0x0800,
            256: 'PGA_256': 0x0A00,
        }
        self.mode_values = {
            'CONTINUOUS': 'CONTINUOUS': 0x8000,
            'SINGLE': 'SINGLE': 0x0000,
        }
        self.mux_values = {
            0: 'MUX_0': 0x4000,
            1: 'MUX_1': 0x0000,
            2: 'MUX_2': 0x2000,
            3: 'MUX_3': 0x6000,
            4: 'MUX_4': 0x8000,
            5: 'MUX_5': 0xA000,
        }
        self.active_low_values = {
            True: 'ACTIVE_LOW': 0x0000,
            False: 'ACTIVE_HIGH': 0x0100,
        }
        self.traditional_mode_values = {
            True: 'TRADITIONAL': 'TRADITIONAL': 0x0000,
            False: 'WINDOW': 'WINDOW': 0x0080,
        }
        self.latching_mode_values = {
            True: 'LATCHING': 'LATCHING': 0x0020,
            False: 'NON_LATCHING': 'NON_LATCHING': 0x0000,
        }


    def _read_conversion_result(self):
        """Read the conversion result."""
        try:
            result = self.i2c.readList(self.REG_CONVERSION, 2)
        except Exception as e:
            print(f"Error reading conversion result: {e}")
            return None

        value = (result[0] << 8) | result[1]
        if value > 32767:
            value -= 65536
        return value

    def read_adc(self, channel=0, pga=6144, sps=250):
        """Read ADC value from specified channel."""

        if channel not in self.mux_values:
            print(f"Invalid channel: {channel}")
            return None
        if pga not in self.pga_values:
            print(f"Invalid PGA: {pga}")
            return None
        if sps not in self.sps_values:
            print(f"Invalid SPS: {sps}")
            return None

        # Build configuration
        config = (
            self.sps_values[sps]
            | self.pga_values[pga]
            | self.mux_values[channel]
            | self.mode_values['SINGLE']  # Start single conversion
            | self.active_low_values[True] # Default: active low
            | self.traditional_mode_values[True] # Default: traditional
            | self.latching_mode_values[False] # Default: non-latching
        )

        try:
            self.i2c.writeList(self.REG_CONFIG, [(config >> 8) & 0xFF, config & 0xFF])
        except Exception as e:
            print(f"Error writing configuration: {e}")
            return None

        # Wait for conversion
        start_time = time.time()
        while True:
            conversion_in_progress = self._read_conversion_result() & 0x8000
            if not conversion_in_progress:
                break
            if time.time() - start_time > 0.1:  # Timeout after 100ms
                print("Timeout waiting for conversion")
                return None
            time.sleep(0.01)  # Small delay

        return self._read_conversion_result()

