import cv2
import time
from picamera import PiCamera
from typing import Tuple, List

# Constants for face detection
CASCADE_SCALE_FACTOR = 1.1
CASCADE_MIN_NEIGHBORS = 5
CASCADE_MIN_SIZE: Tuple[int, int] = (30, 30)
FRAME_WIDTH = 450
CAMERA_WARMUP_TIME = 2

def detect_faces(gray_frame: cv2.Mat, cascade: cv2.CascadeClassifier) -> List[Tuple[int, int, int, int]]:
    """Detects faces in a grayscale frame using a provided cascade classifier."""
    return cascade.detectMultiScale(gray_frame, 
                                    scaleFactor=CASCADE_SCALE_FACTOR,
                                    minNeighbors=CASCADE_MIN_NEIGHBORS,
                                    minSize=CASCADE_MIN_SIZE,
                                    flags=cv2.CASCADE_SCALE_IMAGE)

def draw_rectangles(frame: cv2.Mat, rectangles: List[Tuple[int, int, int, int]]) -> None:
    """Draws rectangles around detected faces on the given frame."""
    for (x, y, w, h) in rectangles:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

def process_frame(frame: cv2.Mat, cascade: cv2.CascadeClassifier) -> cv2.Mat:
    """Processes a single frame by detecting faces and drawing rectangles around them."""
    gray: cv2.Mat = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces: List[Tuple[int, int, int, int]] = detect_faces(gray, cascade)
    draw_rectangles(frame, faces)
    return frame

def initialize_camera() -> Tuple[PiCamera, cv2.VideoCapture]:
    """Initializes the Raspberry Pi camera and the OpenCV video capture."""
    try:
        camera: PiCamera = PiCamera()
        camera.resolution = (FRAME_WIDTH, 480)
        time.sleep(CAMERA_WARMUP_TIME)

        video_capture: cv2.VideoCapture = cv2.VideoCapture(0, cv2.CAP_V4L2)
        if not video_capture.isOpened():
            raise IOError("Cannot open webcam")
        return camera, video_capture
    except Exception as e:
        raise RuntimeError(f"Camera initialization failed: {e}")

def release_resources(camera: PiCamera, video_capture: cv2.VideoCapture) -> None:
    """Releases the camera and video capture resources."""
    if camera:
        camera.stop_preview()
        camera.close()
    if video_capture:
        video_capture.release()
    cv2.destroyAllWindows()


def main() -> None:
    """Main function to run the face detection."""
    try:
        camera, video_capture = initialize_camera()
        face_cascade: cv2.CascadeClassifier = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        if face_cascade.empty():
            raise IOError("Unable to load face cascade classifier")

        camera.start_preview()

        while True:
            ret, frame: cv2.Mat = video_capture.read()
            if not ret or frame is None:
                break

            processed_frame: cv2.Mat = process_frame(frame, face_cascade)
            cv2.imshow('Frame', processed_frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except RuntimeError as e:
        print(f"Error: {e}")
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        if 'camera' in locals():
            release_resources(camera, video_capture)

if __name__ == "__main__":
    main()

