#!/usr/bin/env python3

import boto3
import time
import os
from picamera import PiCamera
from picamera.exc import PiCameraError
from contextlib import contextmanager

# Configuration (consider moving to a separate config file)
COLLECTION_ID = 'home'
THRESHOLD = 85
IMAGE_PATH = 'image.jpg'

# Initialize AWS Rekognition client
rekognition_client = boto3.client('rekognition')

@contextmanager
def pi_camera_context():
    """Context manager for PiCamera to ensure proper resource management."""
    camera = None
    try:
        camera = PiCamera()
        yield camera
    except PiCameraError as e:
        print(f"Error initializing PiCamera: {e}")
        raise  # Re-raise the exception to be handled by the calling function
    finally:
        if camera:
            camera.close()


def capture_image(image_path):
    """Captures an image using the Raspberry Pi camera."""
    try:
        with pi_camera_context() as camera:
            time.sleep(2)  # Allow camera to warm up
            camera.capture(image_path)
        print(f"Image captured and saved to {image_path}")
    except Exception as e:
        print(f"Error capturing image: {e}")
        raise


def search_faces(client, image_path, collection_id, threshold):
    """Searches for faces in the given image within the specified Rekognition collection."""
    try:
        with open(image_path, 'rb') as image_file:
            response = client.search_faces_by_image(
                Image={'Bytes': image_file.read()},
                CollectionId=collection_id,
                MaxFaces=1,
                FaceMatchThreshold=threshold
            )
        return response
    except client.exceptions.ClientError as e:
        print(f"Rekognition ClientError: {e}")
        return None
    except Exception as e:
        print(f"Error searching faces: {e}")
        return None


def process_rekognition_response(response):
    """Processes the Rekognition response and prints recognized names."""
    if response and 'FaceMatches' in response and response['FaceMatches']:
        match = response['FaceMatches'][0]
        similarity = match['Similarity']
        external_image_id = match['Face']['ExternalImageId']
        print(f"Matched {external_image_id} with {similarity:.2f}% similarity.")
    else:
        print("No faces recognized.")


def main():
    """Main function to capture image and perform face recognition."""
    try:
        capture_image(IMAGE_PATH)
        response = search_faces(rekognition_client, IMAGE_PATH, COLLECTION_ID, THRESHOLD)
        if response:
            process_rekognition_response(response)
        else:
            print("Face search failed.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

