import cv2
import mxnet as mx
from mxnet import image, nd
from mxnet.gluon.model_zoo import vision as models
from mxnet.gluon.utils import download
import time
import os
import sys
import datetime
import traceback
import signal
import logging

# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

class GracefulKiller:
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    kill_now = False
    def __init__(self):
        signal.signal(signal.SIGINT, self.exit_gracefully)
        signal.signal(signal.SIGTERM, self.exit_gracefully)

    def exit_gracefully(self, signum, frame):
        logging.info('Received signal %s. Shutting down gracefully...', signum)
        self.kill_now = True
        sys.exit(0)


class ImageClassifier:
    """Classifies images using a pre-trained ResNet-50 model."""

    def __init__(self, pretrained_url="http://data.mxnet.io/models/imagenet/synset.txt",
                 image_shape=(3, 224, 224), num_classes=1000):
        """Initializes the ImageClassifier with pre-trained model and settings."""
        self.pretrained_url = pretrained_url
        self.image_shape = image_shape
        self.num_classes = num_classes
        self.net = None
        self.synset = None
        self.image_path = None
        self.camera_index = 0  # Default camera index
        self.killer = GracefulKiller()

    def download_synset(self):
        """Downloads the synset file."""
        try:
            download(self.pretrained_url)
            with open("synset.txt", "r") as f:
                self.synset = [l.rstrip() for l in f]
        except Exception as e:
            logging.error("Error downloading synset: %s", e)
            raise

    def load_model(self, pretrained_model="resnet50_v2"):
        """Loads the pre-trained ResNet-50 model."""
        try:
            self.net = models.get_model(pretrained_model, pretrained=True)
        except Exception as e:
            logging.error("Error loading model: %s", e)
            raise

    def capture_image(self):
        """Captures an image from the camera."""
        cap = None
        try:
            cap = cv2.VideoCapture(self.camera_index)
            if not cap.isOpened():
                raise IOError("Cannot open webcam")
            ret, frame = cap.read()
            if not ret:
                raise IOError("Cannot read frame from webcam")
            return frame
        except IOError as e:
            logging.error("Camera error: %s", e)
            return None
        except Exception as e:
            logging.error("Error capturing image: %s", e)
            return None
        finally:
            if cap is not None:
                cap.release()

    def preprocess_image(self, image):
        """Preprocesses the image for the model."""
        try:
            img = image.resize_short(image, 256)
            img, _ = image.center_crop(img, (224, 224))
