                    format='%(asctime)s %(message)s',
                    datefmt='%Y-%m-%d %H:%M:%S')

# GPIO pin assignments (BCM numbering)
LIGHT_SENSOR_PIN = 17
TEMP_SENSOR_PIN = 4

# Thresholds for warnings
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75

def simulate_light_sensor():
    """Simulates a light sensor reading in lux."""
    # Daytime (06:00-18:00) yields higher lux, nighttime lower lux
    now = datetime.datetime.now().time()
    if 6 <= now.hour < 18:
        return random.randint(600, 1000)
    else:
        return random.randint(100, 300)

def simulate_temperature_sensor():
    """Simulates a temperature sensor reading in Celsius."""
    # Temperature stays within a reasonable range
    return random.randint(20, 30)

def read_pi_temperature():
    """Reads the Raspberry Pi's internal temperature."""
    try:
        process = subprocess.Popen(['vcgencmd', 'measure_temp'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5)
        output, error = process.communicate()
        if error:
            logging.error(f"Error reading Pi temperature: {error.decode()}")
            return None
        temp_str = output.decode().strip()
        if temp_str.startswith("temp="):
            return float(temp_str[5:-2])
        else:
            logging.error(f"Invalid temperature output: {temp_str}")
            return None
    except subprocess.TimeoutExpired:
        logging.error("Timeout reading Pi temperature")
        return None
    except Exception as e:
        logging.error(f"Error reading Pi temperature: {e}")
        return None

def simulate_voltage_current(lux_value):
    """Simulates voltage and current readings based on light level."""
    if lux_value > LOW_LIGHT_THRESHOLD:
        # High light -> solar panel generating power
        voltage = random.uniform(11.5, 12.5)
        current = random.uniform(1.5, 2.5)
    else:
        # Low light -> minimal power draw
        voltage = random.uniform(10.0, 11.0)
        current = random.uniform(0.5, 1.0)
    return voltage, current

def log_data(lux, temp, voltage, current, pi_temp):
    """Logs sensor data to the log file."""
    logging.info(f"Light: {lux} lux, Temp: {temp} °C, Voltage: {voltage:.2f} V, Current: {current:.2f} A, Pi Temp: {pi_temp} °C")

def main():
    """Main function to run the clean energy monitoring system."""
    try:
        while True:
            # Simulate sensor readings with error handling
            try:
                lux = simulate_light_sensor()
                temp = simulate_temperature_sensor()
                pi_temp = read_pi_temperature()
                voltage, current = simulate_voltage_current(lux)

                # Check for low light and high temperature conditions
                if lux < LOW_LIGHT_THRESHOLD:
                    logging.warning("Low light detected!")
                if temp > HIGH_TEMP_THRESHOLD:
                    logging.warning("High temperature detected!")
                    if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
                        logging.critical("High Pi temperature! Simulating system shutdown.")
                        print("Simulating system shutdown due to high temperature.")
                        break # Exit the loop to simulate shutdown

                # Log the data
                log_data(lux, temp, voltage, current, pi_temp)

            except Exception as e:
                logging.error(f"Error during main loop: {e}")

            # Wait before the next iteration
            time.sleep(5)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # Ensure resources are released (none in this simulation)
        print("Exiting program.")

if __name__ == '__main__':
    main()

