import time
import board
import busio
import adafruit_bmp280
import RPi.GPIO as GPIO

# Pressure thresholds for the three LED indicators
LOW_PRESSURE_THRESHOLD = 990
NORMAL_PRESSURE_THRESHOLD = 1010

# GPIO pins connected to the indicator LEDs
LED_PINS = [17, 27, 22]

def initialize_i2c():
    """Initialize the I2C bus for the BMP280 sensor."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        log_error(f"Failed to initialize I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the BMP280 sensor on the given I2C bus."""
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
    except Exception as e:
        log_error(f"Failed to initialize BMP280 sensor: {e}")
        return None

def initialize_gpio(led_pins):
    """Initialize the GPIO pins for the indicator LEDs."""
    GPIO.setmode(GPIO.BCM)
    for pin in led_pins:
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)

def read_pressure(sensor):
    """Read the barometric pressure from the BMP280 sensor."""
    try:
        return sensor.pressure
    except Exception as e:
        log_error(f"Failed to read pressure: {e}")
        return None

def update_indicators(pressure, led_pins):
    """Update the indicator LEDs based on the measured pressure."""
    try:
        if pressure is None:
            return

        if pressure < LOW_PRESSURE_THRESHOLD:
            GPIO.output(led_pins[0], GPIO.HIGH)
            GPIO.output(led_pins[1], GPIO.LOW)
            GPIO.output(led_pins[2], GPIO.LOW)
        elif LOW_PRESSURE_THRESHOLD <= pressure < NORMAL_PRESSURE_THRESHOLD:
            GPIO.output(led_pins[0], GPIO.LOW)
            GPIO.output(led_pins[1], GPIO.HIGH)
            GPIO.output(led_pins[2], GPIO.LOW)
        else:
            GPIO.output(led_pins[0], GPIO.LOW)
            GPIO.output(led_pins[1], GPIO.LOW)
            GPIO.output(led_pins[2], GPIO.HIGH)
    except Exception as e:
        log_error(f"Failed to update indicators: {e}")

def log_error(message):
    """Log an error message to the error log file with a timestamp."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    with open("error.log", "a") as f:
        f.write(f"{timestamp} - {message}\n")

def main():
    """Main function to read pressure and update indicators."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("I2C initialization failed. Exiting.")
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        print("BMP280 sensor initialization failed. Exiting.")
        return

    initialize_gpio(LED_PINS)

    try:
        while True:
            pressure = read_pressure(sensor)
            if pressure is not None:
                print(f"Pressure: {pressure:.2f} hPa")
                update_indicators(pressure, LED_PINS)
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        log_error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

