import smbus2
import time
import logging
import signal
import sys

# Configure logging for the DHT20 humidity and temperature sensor
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

# I2C bus number and device address for the DHT20 sensor
I2C_BUS_NUMBER = 1
DHT20_ADDRESS = 0x40

# Register addresses used for reading and writing to the DHT20
REGISTER_STATUS = 0x71
REGISTER_MEASURE = 0xAC
REGISTER_DATA0 = 0x71
REGISTER_DATA1 = 0x72
REGISTER_DATA2 = 0x73
REGISTER_DATA3 = 0x74
REGISTER_DATA4 = 0x75
REGISTER_DATA5 = 0x76
REGISTER_CRC = 0x77

# Global flag to signal program termination
running = True


class DHT20:
    """Driver for the DHT20 humidity and temperature sensor over I2C."""

    def __init__(self, bus_number=I2C_BUS_NUMBER, address=DHT20_ADDRESS):
        """Open the I2C bus and verify the DHT20 sensor."""
        self.bus_number = bus_number
        self.address = address
        self.bus = None
        try:
            self.bus = smbus2.SMBus(self.bus_number)
            if self.read_status() != 0x00:
                raise RuntimeError("DHT20 verification failed")
        except Exception as init_error:
            logging.error("DHT20 init failed: %s", init_error)
            self.bus = None

    def read_status(self):
        """Read the current status byte from the DHT20."""
        if self.bus is None:
            return 0xFF  # Indicate an error state
        try:
            return self.bus.read_byte_data(self.address, REGISTER_STATUS)
        except Exception as read_error:
            logging.error("DHT20 status read failed: %s", read_error)
            self.bus = None
            return 0xFF

    def start_measurement(self):
        """Trigger a new measurement on the DHT20."""
        if self.bus is None:
            return False
        try:
            self.bus.write_byte_data(self.address, REGISTER_MEASURE, 0x33)
            return True
        except Exception as start_error:
            logging.error("DHT20 measurement start failed: %s", start_error)
            self.bus = None
            return False

    def read_data(self):
        """Read raw data from the DHT20 after a measurement."""
        if self.bus is None:
            return None
        try:
            data = []
            for register in range(REGISTER_DATA0, REGISTER_CRC + 1):
                data.append(self.bus.read_byte_data(self.address, register))
            return data
        except Exception as read_error:
            logging.error("DHT20 data read failed: %s", read_error)
            self.bus = None
            return None

    def calculate_crc(self, data):
        """Compute the CRC-8 checksum for the raw DHT20 data."""
        crc = 0xFF
        for byte in data[:-1]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc = crc << 1
        return crc & 0xFF

    def validate_crc(self, data):
        """Check if the computed CRC matches the stored CRC."""
        computed_crc = self.calculate_crc(data)
        return computed_crc == data[-1]

    def convert_temperature(self, raw_temp):
        """Convert raw temperature data to degrees Celsius."""
        # DHT20 datasheet formula: temperature = -46.85 + 175.72 * raw_temp / 65536.0
        return -46.85 + (175.72 * raw_temp / 65536.0)

    def convert_humidity(self, raw_humidity):
        """Convert raw humidity data to percentage."""
        # DHT20 datasheet formula: humidity = -6.0 + 125.0 * raw_humidity / 65536.0
        return -6.0 + (125.0 * raw_humidity / 65536.0)

    def measure(self):
        """Perform a measurement and return temperature, humidity, and CRC status."""
        if not self.start_measurement():
            return None, None, True

        # Poll the status register until data is ready (STATUS bit 0 is cleared)
        timeout = time.time() + 0.1
        while self.read_status() & 0x01 != 0:
            if time.time() > timeout:
                logging.error("DHT20 measurement timed out")
                return None, None, True
            time.sleep(0.01)

        raw_data = self.read_data()
        if raw_data is None:
            return None, None, True

        if not self.validate_crc(raw_data):
            logging.error("DHT20 CRC error detected")
            return None, None, True

        raw_humidity = (raw_data[1] << 12) | (raw_data[2] << 4) | (raw_data[3] >> 4)
        raw_temperature = (raw_data[3] << 12) | (raw_data[4] << 4) | (raw_data[5] >> 4)

        humidity = self.convert_humidity(raw_humidity)
        temperature = self.convert_temperature(raw_temperature)
        crc_error = not self.validate_crc(raw_data)
        return temperature, humidity, crc_error

    def close(self):
        """Close the I2C bus connection."""
        if self.bus is not None:
            self.bus.close()
            self.bus = None


def signal_handler(sig, frame):
    """Handle termination signals (e.g., SIGINT, SIGTERM)."""
    global running
    logging.info("Termination signal received, exiting gracefully")
    running = False


def main():
    """Main function to measure and print humidity and temperature."""
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    sensor = DHT20()
    if sensor.bus is None:
        logging.error("DHT20 sensor not available")
        sys.exit(1)

    try:
        temperature, humidity, crc_error = sensor.measure()

        if temperature is not None and humidity is not None:
            logging.info("Temperature: %.2f C, Humidity: %.2f %%", temperature, humidity)
            if crc_error:
                logging.warning("CRC error detected, data may be unreliable")
    except Exception as measure_error:
        logging.error("Measurement failed: %s", measure_error)
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

