import serial
import time
import signal
import sys
from datetime import datetime

# UART port and baud rate for the weather station
UART_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600

# Global serial handle for the weather station
weather_port = None


def read_weather_data():
    """Read one line of weather data from the UART port."""
    try:
        line = weather_port.readline().decode("ascii", errors="replace").strip()
        return line
    except Exception as read_error:
        print("Weather read error:", read_error)
        return None


def validate_reading(reading_text):
    """Check if the weather reading is well formed and in range."""
    # Expect exactly three comma separated fields
    fields = reading_text.split(",")
    if len(fields) != 3:
        return False
    try:
        temperature = float(fields[0])
        humidity = float(fields[1])
        pressure = float(fields[2])
        # Reasonable physical bounds for weather readings
        if -40 <= temperature <= 85 and 0 <= humidity <= 100 and 800 <= pressure <= 1200:
            return temperature, humidity, pressure
        return False
    except ValueError:
        return False


def format_output(temperature, humidity, pressure):
    """Format the weather data into a human readable string."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return "{0} Temp={1:5.1f}C Hum={2:4.1f}% Pres={3:6.1f}hPa".format(
        timestamp, temperature, humidity, pressure
    )


def signal_handler(signum, frame):
    """Handle termination signals and close the serial port."""
    print("Closing weather port...")
    if weather_port is not None:
        weather_port.close()
    sys.exit(0)


def main():
    """Continuously read and report weather data."""
    global weather_port
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        # Open the UART port to the weather station
        weather_port = serial.Serial(UART_PORT, BAUD_RATE, timeout=1)
        while True:
            reading_text = read_weather_data()
            if reading_text:
                if validate_reading(reading_text):
                    temperature, humidity, pressure = validate_reading(reading_text)
                    print(format_output(temperature, humidity, pressure))
            time.sleep(1)
    except serial.SerialException as open_error:
        print("Could not open weather port:", open_error)
    finally:
        # Ensure the serial port is closed on exit
        if weather_port is not None:
            weather_port.close()


if __name__ == "__main__":
    main()

