import config
import wificonnection
from umqtt.simple2 import MQTTClient
from time import sleep
import dht
import machine
import sys

# Constants for error handling and retry logic
MAX_RECONNECT_ATTEMPTS = 5
MQTT_RECONNECT_DELAY = 5  # seconds

# Global variables
mqtt_client = None
dht_sensor = None

# --- Utility Functions ---

def config_log(message):
    """Logs configuration information to the console."""
    print(f"[Config] {message}")

def mqtt_log(message):
    """Logs MQTT-related information to the console."""
    print(f"[MQTT] {message}")

def dht_log(message):
    """Logs DHT sensor-related information to the console."""
    print(f"[DHT] {message}")

def error_log(error_message):
    """Logs error messages to the console and creates a topic-specific error log."""
    print(f"[Error] {error_message}")
    with open("error_log.txt", "a") as f:
        f.write(f"{machine.time()} - {error_message}\n")

def create_mqtt_client():
    """Creates and configures the MQTT client."""
    global mqtt_client
    try:
        mqtt_client = MQTTClient(
            client_id=config.mqttclientid,
            server=config.mqttbroker,
            port=config.mqttport,
            user=config.mqttusername,
            password=config.mqttpassword,
            keepalive=10,  # Increased keepalive time
            ssl=config.mqttssl,
        )
        mqtt_log("MQTT client created.")
        return mqtt_client
    except Exception as e:
        error_log(f"Failed to create MQTT client: {e}")
        return None

def connect_mqtt(mqtt_client):
    """Connects to the MQTT broker with retry logic."""
    if mqtt_client is None:
        mqtt_log("MQTT client is not initialized.")
        return False

    for attempt in range(MAX_RECONNECT_ATTEMPTS):
        try:
            mqtt_client.connect()
            mqtt_log(f"Connected to MQTT broker ({config.mqttbroker}) using client ID ({config.mqttclientid}).")
            # Publish Homie device and node configuration
            publish_homie_config(mqtt_client)
            return True
        except Exception as e:
            error_log(f"Failed to connect to MQTT broker (attempt {attempt + 1}): {e}")
            if attempt < MAX_RECONNECT_ATTEMPTS - 1:
                sleep(MQTT_RECONNECT_DELAY)
            else:
                error_log("Max MQTT reconnection attempts reached. Exiting.")
                return False
    return False

def publish_homie_config(mqtt_client):
    """Publishes Homie device and node configuration."""
    try:
        mqtt_client.publish(
            f"homie/{config.homieclientid}/$homie", "4.0"
        )  # Explicitly mention Homie 4.0
        mqtt_client.publish(
            f"homie/{config.homieclientid}/$name", config.homieclientname
        )
        mqtt_client.publish(
            f"homie/{config.homieclientid}/$nodes", config.homienodes
        )
        node_config = {
            "temperature": {"unit": "C", "datatype": "float", "name": "Temperature"},
            "humidity": {"unit": "%", "datatype": "float", "name": "Humidity"},
        }
        for node, config in node_config.items():
            mqtt_client.publish(
                f"homie/{config.homieclientid}/{config.homienodes}/{node}/$name",
                config["name"],
            )
            mqtt_client.publish(
                f"homie/{config.homieclientid}/{config.homienodes}/{node}/$unit",
                config["unit"],
            )
            mqtt_client.publish(
                f"homie/{config.homieclientid}/{config.homienodes}/{node}/$datatype",
                config["datatype"],
            )
            mqtt_client.publish(
                f"homie/{config.homieclientid}/{config.homienodes}/{node}/$settable", "false"
            )
    except Exception as e:
        error_log(f"Failed to publish Homie configuration: {e}")


def read_dht_sensor():
    """Reads data from the DHT22 sensor with retry logic."""
    global dht_sensor
    for attempt in range(3):  # Retry up to 3 times
        try:
            dht_sensor.measure()
            temperature = dht_sensor.temperature()
            humidity = dht_sensor.humidity()
            # Sanity check the readings
            if temperature is not None and humidity is not None and (
                not (-40 <= temperature <= 80 and 0 <= humidity <= 100)
            ):
                error_log(
                    f"Invalid DHT readings: Temperature={temperature}°C, Humidity={humidity}%, Discarding."
                )
                continue  # Discard and retry

            if temperature is not None and humidity is not None:
                dht_log(
                    f"Temperature = {temperature:.1f}°C, Humidity = {humidity:.1f}%"
                )
                return temperature, humidity
            else:
                error_log("Failed to read DHT sensor data.")

        except RuntimeError as e:
            error_log(
                f"DHT read error (attempt {attempt + 1}): {e}"
            )  # More specific error message
        except Exception as e:
            error_log(f"Unexpected error during DHT read: {e}")
        sleep(2)  # Wait before retrying
    error_log("Failed to read DHT sensor after multiple retries.")
    return None, None


def publish_sensor_data(mqtt_client, temperature, humidity):
    """Publishes temperature and humidity data to MQTT."""
    if mqtt_client is None:
        mqtt_log("MQTT client is not initialized.")
        return

    try:
        mqtt_client.publish(
            f"homie/{config.homieclientid}/{config.homienodes}/temperature",
            f"{temperature:.1f}",
        )
        mqtt_client.publish(
            f"homie/{config.homieclientid}/{config.homienodes}/humidity",
            f"{humidity:.1f}",
        )
        mqtt_log("Sensor data published to MQTT.")
    except Exception as e:
        error_log(f"Failed to publish sensor data: {e}")


# --- Main Program ---

def main():
    """Main function to run the IoT gateway."""
    global dht_sensor, mqtt_client

    # Initialize DHT sensor
    try:
        dht_sensor = dht.DHT22(machine.Pin(config.dhtegpiopin, machine.Pin.IN, machine.Pin.PULL_UP))
        sleep(2)  # Allow sensor to stabilize
    except Exception as e:
        error_log(f"Failed to initialize DHT sensor: {e}")
        sys.exit(1)

    # Initialize and connect MQTT client
    mqtt_client = create_mqtt_client()
    if not connect_mqtt(mqtt_client):
        sys.exit(1)

    try:
        while True:
            temperature, humidity = read_dht_sensor()
            if temperature is not None and humidity is not None:
                publish_sensor_data(mqtt_client, temperature, humidity)
            sleep(config.publishtime)

    except KeyboardInterrupt:
        mqtt_log("Exiting program due to keyboard interrupt.")
    except Exception as e:
        error_log(f"An unexpected error occurred: {e}")
    finally:
        if mqtt_client:
            mqtt_client.disconnect()
            mqtt_log("MQTT disconnected.")
        machine.reset()


if __name__ == "__main__":
    main()

