import RPi.GPIO as GPIO
import time

# Pin assignments for the line-following robot
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6
LEFT_MOTOR_PIN = 16
RIGHT_MOTOR_PIN = 26

# Configure GPIO numbering mode
GPIO.setmode(GPIO.BCM)

# Setup GPIO pins for sensors and motors
try:
    GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN)
    GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN)
    GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT)
    GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT)
except Exception as e:
    print("GPIO setup error:", e)
    exit(1)


def read_sensor(pin):
    """Read the state of a single line-following sensor."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print("Sensor read error:", e)
        return None


def control_motors(left_state, right_state):
    """Control the two motors based on sensor readings."""
    try:
        if read_sensor(LEFT_SENSOR_PIN) == 0 and read_sensor(RIGHT_SENSOR_PIN) == 1:
            # Line on left, turn right
            GPIO.output(LEFT_MOTOR_PIN, 1)
            GPIO.output(RIGHT_MOTOR_PIN, 0)
        elif read_sensor(LEFT_SENSOR_PIN) == 1 and read_sensor(RIGHT_SENSOR_PIN) == 0:
            # Line on right, turn left
            GPIO.output(LEFT_MOTOR_PIN, 0)
            GPIO.output(RIGHT_MOTOR_PIN, 1)
        elif read_sensor(LEFT_SENSOR_PIN) == 0 and read_sensor(RIGHT_SENSOR_PIN) == 0:
            # Line detected by both sensors, go straight
            GPIO.output(LEFT_MOTOR_PIN, 1)
            GPIO.output(RIGHT_MOTOR_PIN, 1)
        else:
            # No line detected, stop
            GPIO.output(LEFT_MOTOR_PIN, 0)
            GPIO.output(RIGHT_MOTOR_PIN, 0)
    except Exception as e:
        print("Motor control error:", e)


def main():
    """Main function to run the line-following robot."""
    try:
        for _ in range(20):
            control_motors(LEFT_MOTOR_PIN, RIGHT_MOTOR_PIN)
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Program stopped by user.")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

