import smbus2
import contextlib

# I2C device helper for a Raspberry Pi
DEVICE_BUS = 1
DEVICE_ADDRESS = 0x40


class I2CDevice:
    """Generic I2C device driver with a clean API for the Raspberry Pi."""

    def __init__(self, address, bus_number=DEVICE_BUS):
        # Open the smbus2 handle for the requested I2C bus
        self.address = address
        self.bus_handle = smbus2.SMBus(bus_number)
        self.is_valid = self.probe_device()

    def probe_device(self):
        """Check the I2C device acknowledges the address."""
        # A successful read means the device is present on the bus
        try:
            self.bus_handle.read_byte(self.address)
        except OSError:
            return False
        return True

    def write_byte(self, register, value):
        """Write a single byte to the given register."""
        if not self.is_valid:
            raise RuntimeError("I2C device is not valid")
        self.bus_handle.write_byte_data(self.address, register, value)

    def read_byte(self, register):
        """Read a single byte from the given register."""
        if not self.is_valid:
            raise RuntimeError("I2C device is not valid")
        return self.bus_handle.read_byte_data(self.address, register)

    def close(self):
        """Close the underlying I2C bus handle."""
        self.bus_handle.close()

    def __enter__(self):
        # Context manager entry point for safe resource release
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        # Context manager exit point that always closes the bus
        self.close()


def main():
    """Read and write a register on an I2C device using the helper."""
    device = None
    try:
        # Open the I2C device and verify it is present
        device = I2CDevice(DEVICE_ADDRESS)
        if not device.is_valid:
            raise RuntimeError("I2C device not found")
        device.write_byte(0x00, 0xFF)
        print("Register written successfully")
    except RuntimeError as device_error:
        # Report any I2C failure to the user
        print("I2C error:", device_error)
    finally:
        # Ensure the I2C bus is closed on exit
        if device is not None:
            device.close()


if __name__ == "__main__":
    main()

