# radiation sensor monitor for manufacturing quality control
# Reads radiation levels from a UART sensor and triggers an alarm on GPIO
import serial
import time
import RPi.GPIO as GPIO

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
ALARM_GPIO_PIN = 18
SAFE_THRESHOLD = 50.0


def configure_serial(port, baud, timeout):
    """Open and configure the serial port for the radiation sensor."""
    # Establish the UART connection to the radiation sensor
    return serial.Serial(port, baud, timeout=timeout, write_timeout=1)


def configure_gpio(alarm_pin):
    # Set up the GPIO pin that drives the alarm output
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(alarm_pin, GPIO.OUT)


def read_radiation_level(serial_connection):
    """Read a line from the serial port and return it as a float."""
    # Read a single line of radiation data from the sensor
    raw_line = serial_connection.readline().decode("ascii", errors="replace").strip()
    if not raw_line:
        return None
    return float(raw_line)


def evaluate_alarm(level, alarm_pin, threshold):
    # Drive the alarm output based on the measured radiation level
    if level > threshold:
        GPIO.output(alarm_pin, GPIO.HIGH)
    else:
        GPIO.output(alarm_pin, GPIO.LOW)


def main():
    # Initialize hardware and run the monitoring loop
    serial_connection = None
    try:
        serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, 1)
        configure_gpio(ALARM_GPIO_PIN)
        while True:
            level = read_radiation_level(serial_connection)
            if level is not None:
