# gps_parse_rpi.py
# Reads GPS data from a UART module and parses GGA sentences.
# Target: Raspberry Pi
import serial
import time
import logging

# Configure logging for GPS data processing
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class SimpleGPS:
    """Minimal GPS reader that parses GGA sentences for location data."""

    def __init__(self, port="/dev/serial0", baudrate=9600, bytesize=8, parity="N", stopbits=1):
        """Configure UART parameters for the GPS module."""
        self.port = port
        self.baudrate = baudrate
        self.bytesize = bytesize
        self.parity = parity
        self.stopbits = stopbits
        self.uart = None

    def connect(self):
        """Open the UART connection to the GPS module."""
        try:
            self.uart = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=self.bytesize,
                parity=self.parity,
                stopbits=self.stopbits,
                timeout=1,
            )
            logging.info("GPS connection established")
            return True
        except serial.SerialException as error:
            logging.error("GPS connection failed: %s", error)
            return False

    def close(self):
        """Close the UART connection."""
        if self.uart is not None and self.uart.is_open:
            self.uart.close()
            logging.info("GPS connection closed")

    def read_data(self):
        """Read a line of data from the GPS module, if available."""
        if self.uart is None or not self.uart.is_open:
            return None
        try:
            if self.uart.in_waiting > 0:
                line = self.uart.readline().decode("utf-8", errors="ignore").strip()
                return line
            return None
        except serial.SerialException as error:
            logging.error("Error reading from GPS: %s", error)
            return None

    def parse_gga(self, sentence):
        """Parse a GGA sentence and return location data as a dictionary."""
        if sentence is None or not sentence.startswith("$GPGGA"):
            return None
        parts = sentence.split(",")
        if len(parts) < 15:
            logging.warning("Incomplete GGA sentence: %s", sentence)
            return None
        try:
            data = {
                "utc_time": parts[1],
                "latitude": parts[2],
                "latitude_direction": parts[3],
                "longitude": parts[4],
                "longitude_direction": parts[5],
                "fix_quality": parts[6],
                "num_satellites": parts[7],
            }
            return data
        except ValueError as error:
            logging.error("Error parsing GGA sentence: %s - %s", sentence, error)
            return None


def main():
    """Main function to connect, read, and parse GPS data."""
    gps_module = SimpleGPS()
    if not gps_module.connect():
        return

    try:
        while True:
            line = gps_module.read_data()
            if line:
                location_data = gps_module.parse_gga(line)
                if location_data:
                    logging.info("Parsed GPS data: %s", location_data)
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Stopping GPS data processing")
    finally:
        gps_module.close()


if __name__ == "__main__":
    main()

