import serial
import time
import logging

# Configure logging to a file with timestamps
logging.basicConfig(filename='power_consumption.log', level=logging.INFO, format='%(asctime)s – Power: %(message)s W')

def read_power_data(serial_port):
    """
    Continuously reads power consumption data from the UART serial port.
    Parses each line as a numeric power value and logs it.
    """
    try:
        while True:
            line = serial_port.readline().decode('ascii', errors='replace').strip()
            if line:
                try:
                    power_value = float(line)
                    logging.info(str(power_value))
                except ValueError:
                    print(f"Error: Invalid data received: {line}", file=sys.stderr)
            time.sleep(1)  # Wait for 1 second before the next reading
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        serial_port.close()
        print("Serial port closed.")

if __name__ == "__main__":
    try:
        # Open the serial port for the smart energy meter
        with serial.Serial('/dev/serial0', 9600, timeout=1) as ser:
            read_power_data(ser)
    except serial.SerialException as e:
        print(f"Serial port error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)

