import json
import time
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
import serial

# Configuration for the web service and instrument
SERIAL_PORT = "/dev/ttyUSB0"
SERIAL_BAUDRATE = 9600
LISTEN_ADDRESS = "0.0.0.0"
LISTEN_PORT = 8080
DATA_STORE = [{"id": 1, "name": "item1", "done": False}, {"id": 2, "name": "item2", "done": True}]

# Serial port management
serial_connection = None


def open_serial_port():
    """Opens the serial port to the SCPI instrument."""
    global serial_connection
    try:
        serial_connection = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
        time.sleep(0.1)  # Allow instrument to initialize
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return False
    return True


def close_serial_port():
    """Closes the serial port."""
    global serial_connection
    if serial_connection:
        serial_connection.close()
        print("Serial port closed.")


def query_instrument(scpi_query):
    """Sends an SCPI query to the instrument and returns the response."""
    global serial_connection
    if not serial_connection:
        print("Serial port not open.")
        return None

    try:
        serial_connection.write(scpi_query.encode())
        time.sleep(0.1)  # Wait for response
        response = serial_connection.read(serial_connection.in_waiting)
        return response.decode().strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


class WebServiceHandler(BaseHTTPRequestHandler):
    """Handles incoming HTTP requests for the web service."""

    def do_GET(self):
        """Handles GET requests."""
        if self.path == "/version":
            self.send_version_info()
        elif self.path.startswith("/getdata"):
            self.send_data()
        elif self.path.startswith("/getset/"):
            self.send_item_data(self.path)
        elif self.path.startswith("/getpost/"):
            self.handle_post_request(self.path)
        elif self.path == "/postjson":
            self.handle_json_post()
        else:
            self.send_error(404, "Not found")

    def do_POST(self):
        """Handles POST requests."""
        if self.path == "/postjson":
            self.handle_json_post()
        else:
            self.send_error(405, "Method not allowed")

    def send_version_info(self):
        """Sends the instrument version information."""
        response = query_instrument("*IDN?\n")
        if response:
            self.send_response(200)
            self.send_header("Content-Type", "text/html")
            self.end_headers()
            self.wfile.write(response.encode())
        else:
            self.send_error(503, "Instrument communication failed")

    def send_data(self):
        """Sends the current data store as JSON."""
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(DATA_STORE).encode())

    def send_item_data(self, path):
        """Sends a specific item from the data store as JSON."""
        try:
            item_id = int(path.split("/")[2])
            item = next((item for item in DATA_STORE if item["id"] == item_id), None)
            if item:
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self.end_headers()
                self.wfile.write(json.dumps(item).encode())
            else:
                self.send_error(404, "Item not found")
        except (ValueError, IndexError):
            self.send_error(400, "Invalid item ID")

    def handle_post_request(self, path):
        """Handles POST requests to update a specific item."""
        try:
            item_id = int(path.split("/")[2])
            name = path.split("/")[3]
            item = next((item for item in DATA_STORE if item["id"] == item_id), None)
            if item:
                item["name"] = name
                item["done"] = True
                DATA_STORE[DATA_STORE.index(item)] = item
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self.end_headers()
                self.wfile.write(json.dumps(DATA_STORE).encode())
            else:
                self.send_error(404, "Item not found")
        except (ValueError, IndexError):
            self.send_error(400, "Invalid item ID")

    def handle_json_post(self):
        """Handles JSON POST requests to add a new item."""
        content_length = int(self.headers.get("Content-Length", 0))
        post_data = self.rfile.read(content_length).decode()

        try:
            if "application/json" in self.headers.get_list("Content-Type"):
                new_item = json.loads(post_data)
            else:
                new_item = {}
                new_item.update(dict(self.headers))
                new_item.update(post_data)

            new_item["id"] = len(DATA_STORE) + 1
            new_item["name"] = new_item.get("name", "")
            new_item["done"] = new_item.get("done", False)
            DATA_STORE.append(new_item)

            self.send_response(201)  # Created
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(DATA_STORE).encode())

        except (json.JSONDecodeError, KeyError, TypeError):
            self.send_error(400, "Invalid JSON data")


def run_server():
    """Starts the HTTP server."""
    try:
        server_address = (LISTEN_ADDRESS, LISTEN_PORT)
        httpd = HTTPServer(server_address, WebServiceHandler)
        print(f"Server listening on {LISTEN_ADDRESS}:{LISTEN_PORT}")
        httpd.serve_forever()
    except Exception as e:
        print(f"Server error: {e}")
    finally:
        close_serial_port()


if __name__ == "__main__":
    if open_serial_port():
        run_server()
    else:
        print("Failed to initialize server. Exiting.")

